"""Numeric helpers."""

from pkg.util import slug


def label(text, value):
    """`slug(text)=value`."""
    return f"{slug(text)}={value}"


def clamp(value, low, high):
    """Keep value inside [low, high]."""
    if value < low:
        return low
    if value > high:
        return high
    return value


def window(items, size):
    """First `size` items."""
    return items[:size]

