import importlib
import unittest


class PackagingTest(unittest.TestCase):
    def test_new_module_path(self):
        self.assertTrue(hasattr(importlib.import_module("pkg.helpers.util"), "slug"))

    def test_old_module_path_is_gone(self):
        with self.assertRaises(ModuleNotFoundError):
            importlib.import_module("pkg.util")
